// CSD_RATIONALE_BEGIN
// SMILES isocyanate CSD — fixing the 0% syntax regression by reverting to
// attempt 9's N=C=O-only NCO check, raising T to 1.8 for more diversity.
//
// Root cause of attempts 32-34 failure (0% syntax):
//   Adding the "O=C=N" substring check caused premature span closure on
//   "O=C=NC1": the SMILES grammar incorrectly marks this as IsCompletePrefix
//   (unclosed ring label treated as complete), and "O=C=NC1" contains "O=C=N",
//   so the span was closed with an invalid SMILES.  All 100 examples produced
//   "O=C=NC1>>" which RDKit rejects.
//
// Fix:
//   1. Remove the "O=C=N" check entirely; keep ONLY "N=C=O" (restoring attempt 9).
//   2. Set minSpanLength=8 so the 7-token "O=C=NC1" span never satisfies the
//      close condition even if IsCompletePrefix fires.
//   3. Raise phase-2 temperature from 1.6 to 1.8 for more structural diversity.
//   4. Keep attempt 34's richer guidance (more structural classes shown).
//
// For "O=C=N..." format isocyanates (e.g. O=C=NCCCl), hasNCO=0 so generation
// continues past the false complete, then CloseSpanWithinBudget closes cleanly
// at the longest valid complete prefix.
// CSD_RATIONALE_END
// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   OpenConstrainedSpan: sets currentConstrainedOut:=[], IsValidPrefix([]) by
//     method precondition. ✓
//   Complete+NCO branch: CloseConstrainedSpan postcondition sets
//     insideConstrainedOut:=false (implication vacuous) and
//     currentConstrainedOut:=[]. ✓
//   Complete+noNCO branch: SafeTemperatureConstrainedStep hard-masks to
//     parser-valid tokens plus EOS; AppendConstrainedToken postcondition
//     gives IsValidPrefix(new currentConstrainedOut). EOS → break. ✓
//   Phase1 (SafePenalizedConstrainedStep): same hard-mask guarantees valid
//     next token; AppendConstrainedToken preserves validity. ✓
//   Phase2 (SafeTemperatureConstrainedStep T=1.8): same hard-mask. ✓
//   Phase3 (GroupBoostedConstrainedStep): same hard-mask. ✓
//   Post-loop CloseSpanWithinBudget: postcondition guarantees
//     insideOut ==> parser.IsValidPrefix(currentOut). ✓
//
// Invariant 2 (progress): |generated| <= |generatedPrefix| + steps
//   OpenConstrainedSpan: steps+=1, |generated|+=1 for "<<". Equality. ✓
//   Each loop iteration: exactly one step helper → steps+=1.
//     AppendConstrainedToken adds at most 1 visible token. EOS adds 0. ✓
//   CloseConstrainedSpan inside loop: steps+=1, |generated|+=1 for ">>". ✓
//   EOS + close sub-branch: we check steps<maxSteps before steps+=1, so
//     steps stays ≤ maxSteps and generated grows by at most 1. ✓
//   Post-loop CloseSpanWithinBudget: closeBudget = maxSteps-steps; postcondition
//     |cg| ≤ |generated| + closeBudget ≤ |generatedPrefix| + maxSteps.
//     We set steps:=maxSteps. ✓
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

var steps: nat := 0;

helpers.AppendTaskGuidance(lm, "Generate exactly one valid SMILES for an isocyanate molecule containing N=C=O. Maximize structural diversity across classes: fluoroalkyl (O=C=NCC(F)(F)F, O=C=NCF, O=C=NCCF), chloroalkyl (O=C=NCCCl, O=C=NCCCCl), cyclopentyl (O=C=NC1CCCC1), cyclohexyl (O=C=NC1CCCCC1), benzyl (O=C=NCc1ccccc1), naphthyl (O=C=Nc1ccc2ccccc2c1), pyridyl (O=C=Nc1ccccn1), tert-butyl (O=C=NC(C)(C)C), isopropyl (O=C=NC(C)C), allyl (O=C=NCC=C), propargyl (O=C=NCC#C), ether-chain (O=C=NCCOC), methyl (O=C=NC), ethyl (O=C=NCC). Output ONLY the SMILES string.");

if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

var minSpanLength: nat := 8;
var tokenCount: nat := 0;
var commonTokens: seq<Token> := ["C", "CC", "O"];

while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength {
    var smilesStr := CSDHelpers.PrefixToString(currentConstrainedOut);
    var hasNCO := CSDHelpers.CountSubstring(smilesStr, "N=C=O");
    if hasNCO > 0 {
      if steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      } else {
        break;
      }
    } else {
      var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
      var next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.8, eosToken
      );
      steps := steps + 1;
      if next == eosToken {
        break;
      } else {
        var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
        generated := ag;
        insideConstrainedOut := ai;
        currentConstrainedOut := ac;
        tokenCount := tokenCount + 1;
      }
    }
  } else {
    var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];
    var next := eosToken;

    if tokenCount < 6 {
      next := helpers.SafePenalizedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, commonTokens, 4.0, eosToken
      );
    } else if tokenCount < 20 {
      next := helpers.SafeTemperatureConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, 1.8, eosToken
      );
    } else {
      next := helpers.GroupBoostedConstrainedStep(
        lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 4.0, eosToken
      );
    }

    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && |currentConstrainedOut| >= minSpanLength && steps < maxSteps {
        var smilesStr2 := CSDHelpers.PrefixToString(currentConstrainedOut);
        var nco2 := CSDHelpers.CountSubstring(smilesStr2, "N=C=O");
        if nco2 > 0 {
          var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
          generated := cg;
          insideConstrainedOut := ci;
          currentConstrainedOut := cc;
          steps := steps + 1;
        }
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(lm, parser, generated, currentConstrainedOut, next);
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
      tokenCount := tokenCount + 1;
    }
  }
}

if insideConstrainedOut && steps < maxSteps {
  var closeBudget := maxSteps - steps;
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := maxSteps;
}

cost := steps;

